import (
	"math"

	"github.com/stubbedev/lys-lib/third_party/wayland/wl"
	"github.com/stubbedev/lys-lib/third_party/wayland/xdg"
)

// Wayland type aliases the generated bindings in
// wlr-layer-shell-unstable-v1.xml.go reference. Keep in lockstep with
// the scanner's expectations.
type (
	// BaseProxy is the base type of every generated Wayland proxy.
	BaseProxy = wl.BaseProxy
	// Context carries a proxy's wire connection for requests.
	Context = wl.Context
	// Event is the base type of every generated proxy event.
	Event = wl.Event
	// Surface is a wl_surface.
	Surface = wl.Surface
	// Output is a wl_output.
	Output = wl.Output
	// Seat is a wl_seat: the primary selection device hangs off it.
	Seat = wl.Seat
	// Buffer is a wl_buffer: the toplevel-icon binding posts icon
	// pixels through it.
	Buffer = wl.Buffer
	// XdgPopup is the xdg_popup role; popups created from a layer
	// surface use it.
	XdgPopup = xdg.Popup
	// Toplevel is the xdg_toplevel role; the xdg-dialog binding
	// registers dialogs against it.
	Toplevel = xdg.Toplevel
	// Pointer is a wl_pointer: ext-image-copy-capture's cursor
	// sessions capture the cursor of one.
	Pointer = wl.Pointer
	// Region is a wl_region: pointer confinement takes one.
	Region = wl.Region
)

// NewBuffer forwards wl.NewBuffer for linux-dmabuf's create_immed,
// which allocates the wl_buffer id client-side.
func NewBuffer(ctx *Context) *Buffer { return wl.NewBuffer(ctx) }

func newServerBuffer() *Buffer { return wl.NewServerBuffer() }

// uint16Array decodes a wl_array of 16-bit values (linux-dmabuf's
// tranche_formats), which Event.Array reads as whole 32-bit words,
// dropping an odd count's last value and leaving the padding unread:
// the array's padded words split into their halves, cut to its length.
func uint16Array(event *Event) []uint16 {
	n := int(event.Uint32())
	out := make([]uint16, 0, n/2+1)
	for range (n + 3) / 4 {
		w := event.Uint32()
		out = append(out, uint16(w&math.MaxUint16), uint16(w>>16))
	}
	return out[:n/2]
}

// SafeCast forwards wl.SafeCast for the generated event dispatch, which
// references it unqualified (see the text-input-v3 binding upstream).
func SafeCast[T any](p wl.Proxy) T { return wl.SafeCast[T](p) }

// Reused forwards wl.Reused for the generated constructors of the
// interfaces the scanner's -reuse names.
func Reused[T wl.Reusable](ctx *Context) (T, bool) { return wl.Reused[T](ctx) }
